<?php include "includes/db.php"; $s = oci_parse($conn, "SELECT M.MATCH_ID, L.USER_ID AS LOST_USER, F.USER_ID AS FOUND_USER, U.FULL_NAME AS LOST_NAME, U2.FULL_NAME AS FOUND_NAME FROM MATCHES M JOIN LOST_ITEMS L ON M.LOST_ID = L.LOST_ID JOIN FOUND_ITEMS F ON M.FOUND_ID = F.FOUND_ID JOIN USERS U ON L.USER_ID = U.USER_ID JOIN USERS U2 ON F.USER_ID = U2.USER_ID"); oci_execute($s); while($r=oci_fetch_assoc($s)) { print_r($r); } ?>
